<?php use Hls\Http\View as V; ?>
<?php if($access->can('finance.invoice.create')): ?><section class="panel"><h2>Draft Invoice</h2><form method="post" class="form-grid"><?= $this->csrf() ?><label>Cabang<select name="branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><label>Customer<select name="customer_id" required><?php foreach($customers as $c): if($access->branch((int)$c['branch_id'])): ?><option value="<?= (int)$c['id'] ?>"><?= V::escape($c['code'].' - '.$c['name']) ?></option><?php endif; endforeach ?></select></label><label>Tanggal Invoice<input type="date" name="invoice_date" required></label><label>Jatuh Tempo<input type="date" name="due_date"></label><?php for($i=0;$i<3;$i++): ?><label>Deskripsi <?= $i+1 ?><input name="description[]" maxlength="255" <?= $i===0?'required':'' ?>></label><label>Kuantitas <?= $i+1 ?><input name="quantity[]" type="number" min="0" step="0.001" value="0"></label><label>Harga <?= $i+1 ?><input name="unit_price[]" type="number" min="0" step="0.01" value="0"></label><?php endfor ?><button class="button button-primary" type="submit">Simpan Draft</button></form></section><?php endif ?><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Nomor / Referensi</th><th>Customer</th><th>Cabang</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a href="<?= $this->url('/finance/invoice-detail?id='.(int)$r['id']) ?>"><?= V::escape($r['official_number'] ?: $r['internal_ref']) ?></a></td><td><?= V::escape($r['customer_name']) ?></td><td><?= V::escape($r['branch_name']) ?></td><td><?= V::escape($r['status']) ?></td><td><?= \Hls\Http\View::money($r['total_amount']) ?></td></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><p class="empty-state">Belum ada invoice.</p><?php endif ?></div></section>
